id": "v06", "input": {"packages": [{"name": "app", "cost": 1, "requires": [["x", "a"], ["x", "b"]], "conflicts": []}, {"name": "x", "cost": 2, "requires": [], "conflicts": []}, {"name": "a", "cost": 1, "requires": [], "conflicts": []}, {"name": "b", "cost": 1, "requires": [], "conflicts": []}], "requested": ["app"], "installed": [], "forbidden": []}, "expected": {"status": "ok", "cost": 3, "added": ["app", "x"], "selected": ["app", "x"]}}], "code": "def make_catalog(packages):
