    best_cost = None
    best_added = None
    best_selected = None

    def search(current_selected, current_added, current_cost, current_added_list):
        nonlocal best_plan, best_cost, best_added, best_selected

        if not is_valid(current_selected, catalog, installed_set, forbidden_set):
            return

        if current_cost < best_cost or (current_cost == best_cost and len(current_added_list) < len(best_added) or (len(current_added_list) == len(best_added) and current_added_list < best_added)):
            best_cost = current_cost
            best_added = current_added_list
            best_selected = sorted(current_selected)

        if not current_added_list:
            return

        for name in sorted(current_added_list):
            new_selected = current_selected.copy()
            new_selected.add(name)

            if not is_valid(new_selected, catalog, installed_set, forbidden_set):
                continue

            new_cost = current_cost + catalog[name]["cost"]
            new_added_list = current_added_list.copy()
            new_added_list.append(name)

            search(new_selected, new_added_list, new_cost, new_added_list)

    search(selected, [], 0, [])

