{"action": "replace_code", "code": "def make_catalog(packages):
    catalog = {}
    for package in packages:
        catalog[package["name"]] = package
    return catalog


def check_requirements(selected, package, catalog, forbidden):
    for clause in package["requires"]:
        if not clause:
            return False
        if any(name not in catalog or name in forbidden for name in clause):
            return False
        if not any(name in selected for name in clause):
            return False
    return True


def check_conflicts(selected, package, catalog):
    for conflict in package["conflicts"]:
        if conflict in selected:
            return False
    return True


def is_valid(selected, catalog, installed, forbidden):
    for name in selected:
        if name not in catalog or name in forbidden:
            return False
        if not check_conflicts(selected, catalog[name], catalog):
            return False
        if not check_requirements(selected, catalog[name], catalog, forbidden):
            return False
    return True


def calculate_cost(selected, catalog):
    total = 0
    for name in selected:
        total += catalog[name]["cost"]
    return total


def get_added(selected, installed):
    added = []
    for name in sorted(selected):
        if name not in installed:
            added.append(name)
    return added


def solve(data):
    catalog = make_catalog(data["packages"])
    installed_set = set(data["installed"])
    forbidden_set = set(data["forbidden"])
    requested_set = set(data["requested"])

    for name in installed_set:
        if name not in catalog or name in forbidden_set:
            return {"status": "impossible"}

    for name in requested_set:
        if name not in catalog or name in forbidden_set:
            return {"status": "impossible"}

    selected = set(installed_set)

    for name in requested_set:
        if not is_valid(selected, catalog, installed_set, forbidden_set):
            return {"status": "impossible"}

    best_cost = None
    best_added = None
    best_selected = None

    def search(current_selected, current_added_list, current_cost):
        nonlocal best_cost, best_added, best_selected

        if not is_valid(current_selected, catalog, installed_set, forbidden_set):
            return

        if best_cost is None or current_cost < best_cost or (current_cost == best_cost and len(current_added_list) < len(best_added) or (len(current_added_list) == len(best_added) and current_added_list < best_added)):
            best_cost = current_cost
            best_added = current_added_list
            best_selected = sorted(current_selected)

        for name in sorted(current_added_list):
            new_selected = set(current_selected)
            new_selected.add(name)

            if not is_valid(new_selected, catalog, installed_set, forbidden_set):
                continue

            new_cost = current_cost + catalog[name]["cost"]
            new_added_list = current_added_list.copy()
            new_added_list.append(name)

            search(new_selected, new_added_list, new_cost)

    search(selected, [], 0)

    if best_cost is None:
        return {"status": "impossible"}

    return {
        "status": "ok",
        "cost": best_cost,
        "added": best_added,
        "selected": best_selected
    }
